def minimumMovesStones(grid: list[list[int]]) -> int:
    zeros = []
    extras = []
    for r in range(3):
        for c in range(3):
            if grid[r][c] == 0: zeros.append((r, c))
            elif grid[r][c] > 1: extras.extend([(r, c)] * (grid[r][c] - 1))
    import itertools
    min_moves = float('inf')
    for p in set(itertools.permutations(extras)):
        moves = sum(abs(z[0] - e[0]) + abs(z[1] - e[1]) for z, e in zip(zeros, p))
        min_moves = min(min_moves, moves)
    return min_moves if min_moves != float('inf') else 0

